fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Check if string is non-empty
    if txt.is_empty() {
        return false;
    }
    
    // Get the last character
    let last_char = txt.chars().last().unwrap(); // safe because we checked is_empty()
    
    // Check if last character is ASCII alphabetic
    if !last_char.is_ascii_alphabetic() {
        return false;
    }
    
    // Check the length condition
    let char_count = txt.chars().count();
    if char_count == 1 {
        return true;
    }
    
    // For strings with more than one character, check if second-to-last is space
    let second_last_char = txt.chars().rev().nth(1).unwrap(); // safe because char_count > 1
    second_last_char == ' '
}